export function outcomeOf(resultText) {
  const s = String(resultText ?? "");
  // Real CodeBuddy Bash results spell this "Exit Code:" (capital C) and the
  // value may be negative; the envelope's own last line wins over any lookalike
  // text carried in Stdout.
  let exitCode = null;
  for (const match of s.matchAll(/(?:^|\n)Exit Code:\s*(-?\d+)/gi)) exitCode = Number(match[1]);
  const stderr = /(?:^|\n)Stderr:\s*([\s\S]*)$/.exec(s);
  return {
    exit_code: exitCode,
    stderr: stderr ? stderr[1].trim().slice(0, 400) : "",
  };
}
```

